CREATE TABLE journal_lines (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,journal_entry_id BIGINT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,description VARCHAR(500) NOT NULL,debit DECIMAL(18,2) NOT NULL DEFAULT 0.00,credit DECIMAL(18,2) NOT NULL DEFAULT 0.00,project_id BIGINT UNSIGNED NULL,client_id BIGINT UNSIGNED NULL,vendor_id BIGINT UNSIGNED NULL,subcontract_id BIGINT UNSIGNED NULL,employee_id BIGINT UNSIGNED NULL,cost_code_id BIGINT UNSIGNED NULL,sort_order INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_journal_lines_entry_order(journal_entry_id,sort_order,id),KEY idx_journal_lines_account(account_id),KEY idx_journal_lines_dimensions(project_id,client_id,vendor_id,employee_id),CONSTRAINT fk_journal_lines_entry FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_account FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_vendor FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_subcontract FOREIGN KEY(subcontract_id) REFERENCES subcontracts(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_employee FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_lines_cost_code FOREIGN KEY(cost_code_id) REFERENCES cost_codes(id) ON DELETE RESTRICT,CONSTRAINT chk_journal_lines_sides CHECK((debit>0 AND credit=0) OR(credit>0 AND debit=0)),CONSTRAINT chk_journal_lines_sort CHECK(sort_order>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
